// Pseudocode: CustomerService command handler
fun handleReserveCredit(cmd: ReserveCredit): CreditReservedEvent {
    db.transaction {
        val customer = db.findCustomer(cmd.customerId)
        if (customer.availableCredit < cmd.amount) {
            db.insert(OutboxEvent(CreditDenied(cmd.orderId)))
            return
        }
        customer.availableCredit -= cmd.amount
        db.save(customer)
        db.insert(OutboxEvent(CreditReserved(cmd.orderId, cmd.amount)))
    }
    // Outbox poller publishes to message broker outside transaction
}

// Participant idempotency pattern
fun handleReserveCredit(cmd: ReserveCredit) {
    db.transaction {
        // Check if already processed
        if (db.existsProcessedCommand(cmd.sagaStepId)) {
            return db.getStoredReply(cmd.sagaStepId)  // return cached reply
        }
        // Execute the step
        val result = performReservation(cmd)
        // Store result and mark as processed atomically
        db.saveProcessedCommand(cmd.sagaStepId, result)
        db.insert(OutboxEvent(result))
    }
}
